from png_util import unfilter_png

for idx in range(6):
    w, h, lines = unfilter_png(f'/tmp/f101_col_{idx}.png')
    # Column center in local crop is around (60, 60)
    col_pts = []
    for y in range(40, 80):
        for x in range(40, 80):
            r, g, b, a = lines[y][x*4:(x+1)*4]
            if 70 < r < 100 and 80 < g < 110 and 90 < b < 120:
                col_pts.append((x, y))
    col_cx = sum(p[0] for p in col_pts)/len(col_pts)
    col_cy = sum(p[1] for p in col_pts)/len(col_pts)

    # find red heads in crop
    red_pts = []
    for y in range(h):
        for x in range(w):
            r, g, b, a = lines[y][x*4:(x+1)*4]
            if r > 120 and g < 70 and b < 70 and a > 200:
                red_pts.append((x, y))
    # cluster them
    clusters = []
    for p in red_pts:
        x, y = p
        matched = False
        for c in clusters:
            cx, cy = c['sum_x']/c['count'], c['sum_y']/c['count']
            if abs(x - cx) < 8 and abs(y - cy) < 8:
                c['sum_x'] += x; c['sum_y'] += y; c['count'] += 1; c['pts'].append(p); matched = True; break
        if not matched: clusters.append({'sum_x': x, 'sum_y': y, 'count': 1, 'pts': [p]})
    print(f'=== Column {idx} (center px {col_cx:.1f}, {col_cy:.1f}) ===')
    for c in clusters:
        if c['count'] < 10: continue
        hx, hy = c['sum_x']/c['count'], c['sum_y']/c['count']
        dx_px = hx - col_cx
        dy_px = hy - col_cy
        dx_mm = dx_px * 38.1025
